/// TaskImportInput says how to read a file of tasks into a project.
@freezed
abstract class TaskImportInput with _$TaskImportInput {
  /// Creates a [TaskImportInput].
  const factory TaskImportInput({
    /// Content is the file itself, for a caller that sends it inside a JSON body
    /// rather than as the upload; the upload wins when both are given.
    @JsonKey(name: 'content') String? content,

    /// DryRun reads and checks the whole file and reports what would happen,
    /// writing nothing.
    @JsonKey(name: 'dry_run') bool? dryRun,

    /// Filename is the uploaded file's name, which helps tell its format.
    @JsonKey(name: 'filename') String? filename,

    /// TaskFormat is a file format a project's tasks are exported in.
    @JsonKey(name: 'format') String? format,

    /// Mapping is a mapping file, YAML or JSON: which column fills which field, how
    /// values translate, and what to do with unknown ones. Empty uses the suggested
    /// mapping, which reads a tix export and the common headers of Jira, GitHub,
    /// Trello and Linear as they are.
    @JsonKey(name: 'mapping') String? mapping,

    /// TaskImportMode says what an import does with a row that matches a task the
    /// project already has, by external id or reference.
    @JsonKey(name: 'mode') String? mode,

    /// Preview is how many rows a dry run shows as tix would create them, 20 when
    /// zero, at most 200.
    @JsonKey(name: 'preview') int? preview,

    /// ProjectRef is the key or identifier of the project to import into. Required.
    @JsonKey(name: 'project_ref') String? projectRef,
  }) = _TaskImportInput;

  /// Reads a [TaskImportInput] from its JSON object.
  factory TaskImportInput.fromJson(Map<String, dynamic> json) =>
      _$TaskImportInputFromJson(json);
}

