    List<TaskImportError> errors,
    @JsonKey(name: 'failed') @Default(0) int failed,

    /// TaskFormat is a file format a project's tasks are exported in.
    @JsonKey(name: 'format') @Default('') String format,

    /// Mapping is the mapping in force, as a mapping file, to save and pass back
