    /// Preview is the first rows as tix would write them.
    @JsonKey(name: 'preview')
    @Default(<TaskImportRow>[])
    List<TaskImportRow> preview,

    /// Rows is how many rows the file holds.
    @JsonKey(name: 'rows') @Default(0) int rows,
    @JsonKey(name: 'skipped') @Default(0) int skipped,

